/* Exact rational generator-span laboratory; fixed-coordinate subject models. */
(() => {
'use strict';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gcd=(a,b)=>{a=a<0n?-a:a;b=b<0n?-b:b;while(b){[a,b]=[b,a%b];}return a;};
class Q {constructor(n,d=1n){n=BigInt(n);d=BigInt(d);if(!d)throw Error('Zero divisor.');if(d<0n){n=-n;d=-d;}const g=gcd(n,d);this.n=n/g;this.d=d/g;}add(b){return new Q(this.n*b.d+b.n*this.d,this.d*b.d);}neg(){return new Q(-this.n,this.d);}sub(b){return this.add(b.neg());}mul(b){return new Q(this.n*b.n,this.d*b.d);}div(b){return new Q(this.n*b.d,this.d*b.n);}toString(){return String(this.n)+(this.d===1n?'':'/'+this.d);}}
const q=x=>new Q(x),zero=q(0),one=q(1),cp=A=>A.map(r=>r.map(v=>new Q(v.n,v.d))),values=A=>A.map(r=>r.map(String));
const eq=(a,b)=>a.n===b.n&&a.d===b.d;
const multiply=(A,B)=>A.map(r=>B[0].map((_,j)=>r.reduce((s,a,k)=>s.add(a.mul(B[k][j])),zero)));
const same=(A,B)=>A.length===B.length&&A.every((r,i)=>r.every((a,j)=>eq(a,B[i][j])));
const mathNum=x=>{const a=String(x).split('/');const mn=s=>s.startsWith('-')?'<mrow><mo>−</mo><mn>'+s.slice(1)+'</mn></mrow>':'<mn>'+esc(s)+'</mn>';return a.length===2?'<mfrac>'+mn(a[0])+mn(a[1])+'</mfrac>':mn(a[0]);};
const matrixMath=A=>'<math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mo>[</mo><mtable>'+A.map(r=>'<mtr>'+r.map(v=>'<mtd>'+mathNum(v)+'</mtd>').join('')+'</mtr>').join('')+'</mtable><mo>]</mo></mrow></math>';
const tx=(x,y,s,cls='label',anchor='start')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" class="vs-${cls}">${esc(s)}</text>`;
function cellLabel(x,y,v){const parts=String(v).split('/');if(parts.length===1)return tx(x+38.5,y+37,String(v).replace('-','−'),'math','middle');const tiny=(s,dy)=>{let z=tx(x+38.5,y+dy,s.replace('-','−'),'math','middle').replace('<text','<text style="font-size:18px"');if(s.length>6)z=z.replace('<text','<text textLength="59" lengthAdjust="spacingAndGlyphs"');return z;};return tiny(parts[0],22)+`<line x1="${x+9}" y1="${y+29}" x2="${x+68}" y2="${y+29}" stroke="#304c61" stroke-width="1.2"/>`+tiny(parts[1],47);}
function grid(A,hot=-1){let s='';A.forEach((r,i)=>r.forEach((v,j)=>{const x=65+j*87,y=115+i*70;s+=`<g data-entity="cell-${i}-${j}"><rect x="${x}" y="${y}" width="77" height="58" rx="7" fill="${i===hot?'#f3deb7':'#e6efea'}" stroke="#b0c4c5"/>`+cellLabel(x,y,v)+'</g>';}));return s;}
function reduce(input,keepSteps=true){const A=cp(input),rows=A.length,cols=A[0].length,E=Array.from({length:rows},(_,i)=>Array.from({length:rows},(_,j)=>q(i===j?1:0))),pivots=[],steps=[];const save=(operation,hot=-1)=>{if(keepSteps)steps.push({A:cp(A),E:cp(E),operation,hot,verified:same(multiply(E,input),A)});};save('Read the original matrix');let r=0;
for(let c=0;c<cols&&r<rows;c++){let p=r;while(p<rows&&!A[p][c].n)p++;if(p===rows)continue;if(p!==r){[A[r],A[p]]=[A[p],A[r]];[E[r],E[p]]=[E[p],E[r]];save('Swap rows '+(r+1)+' and '+(p+1),r);}const d=A[r][c];if(!eq(d,one)){A[r]=A[r].map(v=>v.div(d));E[r]=E[r].map(v=>v.div(d));save('Divide row '+(r+1)+' by '+d,r);}for(let i=0;i<rows;i++){if(i===r||!A[i][c].n)continue;const a=A[i][c];A[i]=A[i].map((v,j)=>v.sub(a.mul(A[r][j])));E[i]=E[i].map((v,j)=>v.sub(a.mul(E[r][j])));save('R'+(i+1)+' becomes R'+(i+1)+' minus ('+a+') R'+(r+1),i);}pivots.push(c);r++;}return {A,E,pivots,steps};}
function spanLab(input,target){const original=input.map(r=>r.map(q)),b=target.map(q),rr=reduce(original),n=original[0].length,pivots=rr.pivots,free=Array.from({length:n},(_,j)=>j).filter(j=>!pivots.includes(j)),basis=pivots.map(j=>original.map(r=>r[j])),nullBasis=free.map(j=>{const v=Array.from({length:n},()=>zero);v[j]=one;pivots.forEach((p,i)=>v[p]=rr.A[i][j].neg());return v;});
const augmented=original.map((r,i)=>[...r,b[i]]),ar=reduce(augmented),consistent=!ar.pivots.includes(n),coefficients=Array.from({length:n},()=>zero);if(consistent)ar.pivots.forEach((p,i)=>coefficients[p]=ar.A[i][n]);
const kernelVerified=nullBasis.every(v=>multiply(original,v.map(a=>[a])).every(r=>!r[0].n)),targetVerified=!consistent||same(multiply(original,coefficients.map(a=>[a])),b.map(a=>[a]));
const result={rank:pivots.length,pivotColumns:pivots.map(x=>x+1),basis:basis.map(v=>v.map(String)),nullBasis:nullBasis.map(v=>v.map(String)),consistent,coefficients:consistent?coefficients.map(String):null,checks:{kernelVerified,targetVerified,rankNullity:pivots.length+nullBasis.length===n}};
if(!Object.values(result.checks).every(Boolean)||[...rr.steps,...ar.steps].some(s=>!s.verified))throw Error('An internal exact-arithmetic verification failed; no result has been accepted.');
const m={id:'editable',title:'Your generator span and target',kind:'exact-generator-row-reduction',invariant:'Columns of the supplied original matrix are the generators. Exact rational row operations preserve their relations. Pivot indices select original columns; free variables generate the kernel.',code:['Keep the original generators.','Use exact reversible row operations.','Select original columns by pivot indices.','Solve free coefficients for the kernel.','Check target consistency in the augmented system.'],frames:[],result};
function add(step,phase){const A=step.A,snapshot={matrix:values(A),rowOperator:values(step.E),phase,rank:result.rank,consistent},s=tx(35,32,phase)+grid(values(A),step.hot)+tx(650,145,'Generator rank = '+result.rank,'math')+tx(650,205,'Pivot columns: '+(result.pivotColumns.join(', ')||'none'))+tx(650,265,'Kernel dimension = '+free.length,'math')+tx(65,465,step.operation)+tx(65,515,'Exact row-operator check E × input = current matrix: '+step.verified);const previous=m.frames.at(-1)?.snapshot,changes=previous?Object.entries(snapshot).filter(([k,v])=>JSON.stringify(previous[k])!==JSON.stringify(v)).map(([field,after])=>({field,before:previous[field],after})):[];
m.frames.push({snapshot,svg:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 570" role="img" data-visual-type="plot">${s}</svg>`,caption:phase==='Generator reduction'?'The pivot columns select vectors from your original matrix. The working columns are transformed and must not be substituted for that original basis.':'The final column is the target. A pivot there proves inconsistency; otherwise set free coefficients to zero for one particular representation.',formulaHtml:matrixMath(values(A)),teaching:{operation:step.operation,why:'Every displayed operation has an independently tracked exact row operator. The final answers are separately checked against the original input.',checks:[{mathHtml:matrixMath(values(multiply(step.E,phase==='Generator reduction'?original:augmented))),result:String(step.verified)}],changes,currentState:snapshot,initial:m.frames.length===0,reading:m.invariant,guide:m.code,activeLine:phase==='Generator reduction'?1:4,mode:m.kind}});}
rr.steps.forEach(step=>add(step,'Generator reduction'));ar.steps.forEach(step=>add(step,'Augmented target reduction'));return m;}
const controls=()=>'<div class="vs-controls"><button type="button" data-reset>Restart</button><button type="button" data-prev>Previous</button><button type="button" data-play>Play</button><button type="button" data-next>Next</button><label>Speed<select data-speed><option value="2600">Slow</option><option value="1800" selected>Normal</option><option value="1300">Fast</option></select></label><label>Step<input type="range" data-seek min="0" value="0" aria-label="Laboratory checkpoint"></label></div><div class="vs-stage"></div><p class="vs-caption"></p><p data-progress></p><div class="vs-formula formula-block"></div><div class="vs-print"></div>';
function mount(host,m){return AdvancedSimulations.mount(host,m,{topic:"l_spaces",prefix:"vs"});}

const api={Q,reduce,spanLab};if(typeof module!=='undefined'){module.exports=api;return;}globalThis.VectorSpaceModels=api;
async function boot(){const data=await(await fetch('l_spaces-models.json')).json();globalThis.VectorSpacePlayers=[];for(const host of document.querySelectorAll('[data-vs-model]')){const m=data.models.find(x=>x.id===host.dataset.vsModel);if(!m)throw Error('Missing vector-space model.');VectorSpacePlayers.push(mount(host,m));}
const form=document.querySelector('#vs-form'),out=document.querySelector('#vs-output'),error=document.querySelector('#vs-error');let current=null;
form.addEventListener('submit',event=>{event.preventDefault();try{const rows=form.elements.matrix.value.trim().split(';').map(r=>r.split(',').map(v=>v.trim())),target=form.elements.target.value.trim().split(',').map(v=>v.trim());const valid=x=>/^[-+]?\d+$/.test(x)&&Math.abs(Number(x))<=20;if(rows.length<2||rows.length>4||rows[0].length<1||rows[0].length>5||rows.some(r=>r.length!==rows[0].length)||!rows.flat().every(valid)||target.length!==rows.length||!target.every(valid))throw Error('Use 2–4 equal-length rows, 1–5 columns, and integer entries from −20 to 20. The target must have one entry per row.');const m=spanLab(rows.map(r=>r.map(Number)),target.map(Number));current?.dispose();out.innerHTML='<section class="vs-model" tabindex="0"><h3>'+esc(m.title)+'</h3><p>'+esc(m.invariant)+'</p>'+controls()+'</section><section class="lab-results"><h3>Exact endpoint, checked against the original generators</h3><p>Rank: '+m.result.rank+'. Original pivot columns: '+(m.result.pivotColumns.join(', ')||'none')+'.</p><p>Basis vectors (as columns):</p>'+matrixMath(m.result.basis.length?rows.map((_,i)=>m.result.basis.map(v=>v[i])):Array.from({length:rows.length},()=>['0']))+(m.result.basis.length?'':'<p>The displayed zero column is only a placeholder; the basis of the zero space is the empty list.</p>')+'<p>Null-space basis vectors:</p>'+m.result.nullBasis.map(v=>matrixMath(v.map(x=>[x]))).join('')+(m.result.nullBasis.length?'':'<p>The kernel is {0}, with an empty basis.</p>')+'<p>'+ (m.result.consistent?'The target belongs to the span. One coefficient vector is:':'The target does not belong to the span. The augmented system is inconsistent.')+'</p>'+(m.result.consistent?matrixMath(m.result.coefficients.map(x=>[x])):'')+'<p>Independent exact checks: kernel vectors, target representation when consistent, and rank–nullity all pass.</p></section>';current=mount(out.firstChild,m);globalThis.VectorSpaceLab=current;error.textContent='';}catch(err){error.textContent=err.message;}});
}
boot().catch(err=>{const p=document.createElement('p');p.setAttribute('role','alert');p.textContent='The interactive laboratory could not initialize: '+err.message;document.querySelector('.lesson').prepend(p);throw err;});
})();
